/* Sticker basket: drag, drop, stick. Saved per visitor with localStorage. */
(() => {
  // SWAP THESE for your images, e.g. { id:'moth', theme:'moon', src:'stickers/moth.gif' }
  const STICKERS = [
    { id:'moon', theme:'moon', src:'data:image/gif;base64,' },
    { id:'burst', theme:'moon', src:'data:image/gif;base64,' },
    { id:'star', theme:'moon', src:'data:image/gif;base64,' },
    { id:'pearls', theme:'moon', src:'data:image/gif;base64,' },
    { id:'cowrie', theme:'moon', src:'data:image/png;base64,' },
    { id:'heart', theme:'moon', src:'data:image/gif;base64,' },
    { id:'beetle_blue', theme:'pond', src:'data:image/png;base64,' },
    { id:'beetle_teal', theme:'pond', src:'data:image/png;base64,' },
    { id:'dragonfly', theme:'pond', src:'data:image/gif;base64,' },
    { id:'clover', theme:'pond', src:'data:image/png;base64,' },
    { id:'leaf_pink', theme:'pond', src:'data:image/png;base64,' },
    { id:'locket', theme:'pond', src:'data:image/gif;base64,' },
    { id:'monarch', theme:'autumn', src:'data:image/gif;base64,' },
    { id:'apple', theme:'autumn', src:'data:image/png;base64,' },
    { id:'orange', theme:'autumn', src:'data:image/png;base64,' },
    { id:'oak_leaf', theme:'autumn', src:'data:image/png;base64,' },
    { id:'kitten', theme:'autumn', src:'data:image/gif;base64,' },
    { id:'sun_pin', theme:'autumn', src:'data:image/gif;base64,' },
    { id:'acorn', theme:'autumn', src:'data:image/png;base64,' },
  ];
  const KEY = 'stickers:' + location.pathname, MAX = 60;
  let items = [], selected = null, hidden = false;
  try { const s = JSON.parse(localStorage.getItem(KEY)); if (Array.isArray(s)) items = s.filter(i => i && STICKERS.some(k => k.id === i.id)).slice(0, MAX); } catch {}
  const save = () => { try { localStorage.setItem(KEY, JSON.stringify(items)); } catch {} };

  const css = document.createElement('style');
  css.textContent = `
  .stk-layer{position:absolute;left:0;top:0;width:100%;height:0;z-index:900}
  .stk{position:absolute;translate:-50% -50%;cursor:grab;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;image-rendering:pixelated}
  .stk.sel{outline:2px dashed var(--ink,#fff);outline-offset:2px}
  .stk-ui{position:fixed;right:12px;bottom:12px;z-index:1000;display:flex;flex-direction:column;align-items:flex-end;gap:6px;font:18px VT323,'Courier New',monospace}
  .stk-ui button{font:inherit;color:var(--btnink,#050420);background:var(--btn,#d8d2de);border:3px outset var(--btn,#fff);padding:3px 9px;cursor:pointer}
  .stk-ui button:active{border-style:inset}
  .stk-ui [hidden]{display:none!important}
  .stk-tray{background:var(--bar,#3430c8);color:#fff;border:5px ridge var(--edge,#b0aaff);padding:8px;width:232px}
  .stk-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:4px}
  .stk-ui .stk-grid button{background:var(--panel,#050420);border:3px inset var(--edge,#b0aaff);padding:5px;aspect-ratio:1;touch-action:none}
  .stk-grid img{width:100%;height:100%;object-fit:contain;display:block;pointer-events:none;image-rendering:pixelated}
  .stk-row{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px;justify-content:flex-end}
  .stk-ui p{margin:6px 0 0}`;
  document.head.append(css);

  const el = (tag, cls, text) => { const n = document.createElement(tag); if (cls) n.className = cls; if (text) n.textContent = text; return n; };
  const btn = (text, fn, cls) => { const b = el('button', cls, text); b.type = 'button'; if (fn) b.onclick = fn; return b; };
  const layer = el('div','stk-layer'), ui = el('div','stk-ui'), tools = el('div','stk-row'),
        tray = el('div','stk-tray'), grid = el('div','stk-grid'), row = el('div','stk-row'), note = el('p');
  tray.hidden = true; tools.hidden = true; note.setAttribute('role','status');

  const clamp = (v,a,b) => Math.min(b, Math.max(a, v));
  const pageH = () => document.body.getBoundingClientRect().height;
  const place = (n, it) => { n.style.left = it.x*100+'%'; n.style.top = it.y+'px'; n.style.width = it.s+'px'; n.style.rotate = it.r+'deg'; };

  function render(focus) {
    layer.replaceChildren(...items.map((it, i) => {
      const n = el('img', 'stk' + (it === selected ? ' sel' : ''));
      n.src = STICKERS.find(k => k.id === it.id).src; n.alt = it.id + ' sticker'; n.draggable = false; n.tabIndex = 0;
      place(n, it);
      n.onpointerdown = e => { e.preventDefault(); select(it, n); drag(e, it, n); };
      n.onfocus = () => select(it, n);
      n.onkeydown = e => {
        const m = {ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,-10],ArrowDown:[0,10]}[e.key];
        if (m) { e.preventDefault(); move(it, it.x*innerW() + m[0], it.y + m[1]); place(n, it); save(); }
        if (e.key === 'Delete' || e.key === 'Backspace') { e.preventDefault(); remove(); }
      };
      return n;
    }));
    layer.hidden = hidden;
    tools.hidden = !selected || hidden;
    if (focus) layer.children[items.indexOf(focus)]?.focus({preventScroll:true});
  }
  const innerW = () => document.documentElement.clientWidth;
  function move(it, px, py) { it.x = clamp(px / innerW(), .04, .96); it.y = clamp(py, 20, Math.max(20, pageH() - 20)); }
  function select(it, n) {
    selected = it; layer.querySelectorAll('.sel').forEach(x => x.classList.remove('sel'));
    n?.classList.add('sel'); tools.hidden = false;
  }
  function drag(e, it, n) {
    const dx = it.x*innerW() - e.pageX, dy = it.y - e.pageY;
    n.setPointerCapture(e.pointerId);
    n.onpointermove = ev => { move(it, ev.pageX + dx, ev.pageY + dy); place(n, it); };
    n.onpointerup = n.onpointercancel = () => { n.onpointermove = null; save(); };
  }
  function add(id, px, py) {
    if (items.length >= MAX) { note.textContent = 'page is full! remove a sticker first.'; return; }
    const it = { id, s: 90, r: Math.round(Math.random()*30 - 15), x: 0, y: 0 };
    move(it, px, py); items.push(it); selected = it; hidden = false; hide.textContent = 'put away'; note.textContent = '';
    save(); render(it);
  }
  function remove() { items = items.filter(i => i !== selected); selected = null; note.textContent = ''; save(); render(); }
  function change(fn) { if (!selected) return; fn(selected); save(); render(); }

  STICKERS.forEach(k => {
    const b = btn(''); b.dataset.t = k.theme; b.setAttribute('aria-label', 'add ' + k.id + ' sticker');
    const img = el('img'); img.src = k.src; img.alt = ''; b.append(img);
    let ghost = null, start = null;
    b.onpointerdown = e => { start = e; b.setPointerCapture(e.pointerId); };
    b.onpointermove = e => {
      if (!start) return;
      if (!ghost && Math.hypot(e.clientX-start.clientX, e.clientY-start.clientY) > 6) {
        ghost = el('img','stk'); ghost.src = k.src; ghost.style.cssText = 'position:fixed;width:90px;z-index:1100;pointer-events:none'; document.body.append(ghost);
      }
      if (ghost) { ghost.style.left = e.clientX+'px'; ghost.style.top = e.clientY+'px'; }
    };
    const end = e => {
      if (ghost) {
        ghost.remove(); ghost = null;
        const r = tray.getBoundingClientRect();
        const backInTray = e.clientX >= r.left && e.clientX <= r.right && e.clientY >= r.top && e.clientY <= r.bottom;
        if (e.type === 'pointerup' && !backInTray) add(k.id, e.pageX, e.pageY);
      } else if (e.type === 'pointerup') add(k.id, innerW()*(.25 + Math.random()*.4), scrollY + innerHeight*(.2 + Math.random()*.3));
      start = null;
    };
    b.onpointerup = b.onpointercancel = end;
    b.onlostpointercapture = () => { ghost?.remove(); ghost = null; start = null; };
    b.onclick = e => { if (e.detail === 0) add(k.id, innerW()/2, scrollY + innerHeight/3); }; // keyboard
    grid.append(b);
  });

  const hide = btn('put away', () => { hidden = !hidden; hide.textContent = hidden ? 'bring back' : 'put away'; render(); });
  let armed;
  const clear = btn('clear all', () => {
    if (!armed) { clear.textContent = 'sure?'; armed = setTimeout(() => { armed = null; clear.textContent = 'clear all'; }, 3000); return; }
    clearTimeout(armed); armed = null; clear.textContent = 'clear all'; items = []; selected = null; save(); render();
  });
  tools.append(
    btn('↺', () => change(i => i.r -= 15)), btn('↻', () => change(i => i.r += 15)),
    btn('−', () => change(i => i.s = Math.max(40, i.s - 15))), btn('+', () => change(i => i.s = Math.min(240, i.s + 15))),
    btn('to front', () => change(i => { items = items.filter(x => x !== i).concat(i); })),
    btn('remove', remove));
  ['rotate left','rotate right','smaller','bigger'].forEach((l,i) => tools.children[i].setAttribute('aria-label', l));
  row.append(hide, clear); tray.append(grid, row, note);
  const basket = btn('* sticker basket *', () => { tray.hidden = !tray.hidden; basket.setAttribute('aria-expanded', !tray.hidden); }, 'stk-basket');
  basket.setAttribute('aria-expanded', false);
  const THEMES = ['moon','pond','autumn'];
  const WINDOWS = { moon:'data:image/gif;base64,', pond:'data:image/gif;base64,', autumn:'data:image/gif;base64,' };
  const skin = el('style'); skin.textContent = THEMES.map(t => `:root[data-theme=${t}] .stk-grid button:not([data-t=${t}]){display:none}`).join('');
  const themeBtn = btn('', () => setTheme(THEMES[(THEMES.indexOf(document.documentElement.dataset.theme) + 1) % THEMES.length]), 'stk-basket');
  function setTheme(t) {
    document.documentElement.dataset.theme = t; themeBtn.textContent = '* theme: ' + t + ' *';
    document.querySelectorAll('img.hero').forEach(h => { h.src = WINDOWS[t]; h.alt = 'animated ' + t + ' window scene'; });
    try { localStorage.setItem('theme', t); } catch {}
  }
  document.head.append(skin);
  const dock = el('div','stk-row'); dock.append(themeBtn, basket);
  let start = 'moon'; try { const s = localStorage.getItem('theme'); if (THEMES.includes(s)) start = s; } catch {}
  basket.classList.add('stk-open');
  setTheme(start);
  ui.append(tools, tray, dock); document.body.append(layer, ui);
  document.addEventListener('pointerdown', e => { if (!e.target.closest('.stk,.stk-ui')) { selected = null; render(); } });
  render();
})();
